r<-readRDS('terminal/fits.rds');loo<-read.csv('supplement/leave-one-out.csv')
workflow<-function(){par(mar=c(0,0,2,0));plot.new();plot.window(xlim=c(0,1),ylim=c(0,1));title('GUANE empirical workflow');labs<-c('phytools mammal.data + mammal.tree\n49 taxa; kg and km2 verified','Preserve raw inputs; create natural logs\nNo exclusions or imputation','Run signal and BM/REML regression\nGUI controls and exported R code','Recompute in clean terminal sessions\nCompare tables, inputs and diagnostics');for(i in 1:4){y<-1-i*.21;rect(.08,y-.065,.92,y+.065,col='#edf3e9',border='#34765b');text(.5,y,labs[i],cex=.95);if(i<4)arrows(.5,y-.07,.5,y-.135,length=.08)}}
empirical<-function(){par(mfrow=c(2,2),mar=c(5,5,3,2),cex=1.1);d<-r$traits
plot(d$ln_body_mass_kg,d$ln_home_range_km2,pch=19,col='#34765b',xlab='ln(body mass / 1 kg)',ylab='ln(home-range area / 1 km2)',main='A  Specified BM regression');abline(r$pgls$coefficients$Estimate[1],r$pgls$coefficients$Estimate[2],col='#0d5368',lwd=2)
plot(r$pgls$points$Fitted,r$pgls$points$Residual,pch=19,col='#34765b',xlab='Fitted ln(home-range area / 1 km2)',ylab='Normalized residual',main='B  Residual diagnostics');abline(h=0,lty=2)
qqnorm(r$pgls$points$Residual,pch=19,col='#34765b',main='C  Conditional residual Q-Q');qqline(r$pgls$points$Residual,lty=2)
plot(seq_len(49),loo$Slope,ylim=range(loo$Lower,loo$Upper),pch=19,cex=.6,col='#34765b',xlab='Omitted taxon (source tree order)',ylab='Slope with conditional 95% interval',main='D  All 49 omission fits');segments(1:49,loo$Lower,1:49,loo$Upper,col='#79a58e');abline(h=r$pgls$coefficients$Estimate[2],lty=2,col='#0d5368')}
for(i in 1:2){pdf(paste0('figures/figure',i,'.pdf'),width=if(i==1)7 else 12,height=if(i==1)6 else 10);if(i==1)workflow() else empirical();dev.off();png(paste0('figures/figure',i,'.png'),width=if(i==1)1400 else 2400,height=if(i==1)1200 else 2000,res=200);if(i==1)workflow() else empirical();dev.off()}
pdf('supplement/tree-49-taxa.pdf',width=9,height=12);ape::plot.phylo(r$tree,cex=.7);title('Historical mammal tree: 49 matched taxa');ape::axisPhylo();dev.off()
